//! The class attributes of TimeFrame, SpecFrame, DSBSpecFrame and
//! FluxFrame, checked against the C library.
//!
//! `class_attrs_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/class_attrs_probe.c`, which applies each setting
//! to a default object of the class with `astSet`, reads every attribute
//! back with its `astTest` result, and dumps the object. [`make`] applies
//! the same settings through the public API, converting C's attribute units
//! (GHz, km/s, hours, the Frame's current units) to the ones the API takes,
//! so the test also shows which method corresponds to each C attribute.

use crate::common::native_dump;
// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "class_attrs_oracle/cases.rs"]
mod cases;

use cases::V;

use starlink_ast::frames::{
    CmpFrame, DSBSpecFrame, FluxFrame, FluxSystem, Frame, SideBand, SkyFrame, SkySystem, SpecFrame,
    SpecSystem, StdOfRest, TimeFrame, TimeScale, TimeSystem,
};
use starlink_ast::{AnyObject, from_native_string};

enum Obj {
    Time(TimeFrame),
    Spec(SpecFrame),
    Dsb(DSBSpecFrame),
    Flux(FluxFrame),
}

impl Obj {
    fn frame(&self) -> &dyn Frame {
        match self {
            Obj::Time(f) => f,
            Obj::Spec(f) => f,
            Obj::Dsb(f) => f,
            Obj::Flux(f) => f,
        }
    }
    fn any(&self) -> AnyObject {
        match self {
            Obj::Time(f) => AnyObject::TimeFrame(f.clone()),
            Obj::Spec(f) => AnyObject::SpecFrame(f.clone()),
            Obj::Dsb(f) => AnyObject::DSBSpecFrame(f.clone()),
            Obj::Flux(f) => AnyObject::FluxFrame(f.clone()),
        }
    }
}

/// Radians from C's sexagesimal hours or degrees.
fn sexagesimal(text: &str, hours: bool) -> f64 {
    let (sign, rest) = match text.strip_prefix('-') {
        Some(r) => (-1.0, r),
        None => (1.0, text.trim_start_matches('+')),
    };
    let mut v = 0.0;
    let mut scale = 1.0;
    for f in rest.split(':') {
        v += f.parse::<f64>().unwrap() * scale;
        scale /= 60.0;
    }
    sign * (v * if hours { 15.0 } else { 1.0 }).to_radians()
}

fn apply_spec(f: &mut SpecFrame, name: &str, value: &str) -> bool {
    let dbl = || value.parse::<f64>().unwrap();
    match name {
        "System" => f.set_system(SpecSystem::parse(value).unwrap()).unwrap(),
        "AlignSystem" => f.set_align_system(SpecSystem::parse(value).unwrap()),
        "StdOfRest" => f.set_std_of_rest(StdOfRest::parse(value).unwrap()).unwrap(),
        "AlignStdOfRest" => f.set_align_std_of_rest(StdOfRest::parse(value).unwrap()),
        // C reads RestFreq in GHz and SourceVel in km/s.
        "RestFreq" => f.set_rest_freq(dbl() * 1e9),
        "RefRA" => f.set_ref_ra(sexagesimal(value, true)),
        "RefDec" => f.set_ref_dec(sexagesimal(value, false)),
        "SourceVel" => f.set_source_vel_cur(dbl()),
        "SourceVRF" => f.set_source_vrf(StdOfRest::parse(value).unwrap()).unwrap(),
        "SourceSys" => f.set_source_sys(SpecSystem::parse(value).unwrap()).unwrap(),
        "SpecOrigin" => f.set_spec_origin_cur(dbl()).unwrap(),
        "AlignSpecOffset" => f.set_align_spec_offset(value != "0"),
        _ => return false,
    }
    true
}

fn make(class: &str, settings: &str) -> Obj {
    let mut obj = match class {
        "TimeFrame" => Obj::Time(TimeFrame::unset_system()),
        "SpecFrame" => Obj::Spec(SpecFrame::unset_system()),
        "DSBSpecFrame" => Obj::Dsb(DSBSpecFrame::unset_system()),
        _ => Obj::Flux(FluxFrame::unset_system()),
    };
    for setting in settings.split(';').filter(|s| !s.is_empty()) {
        let (name, value) = setting.split_once('=').unwrap();
        let dbl = || value.parse::<f64>().unwrap();
        if name == "Format(1)" {
            match &mut obj {
                Obj::Time(f) => Frame::set_format_str(f, 1, value).unwrap(),
                _ => unreachable!(),
            }
            continue;
        }
        if name == "Unit(1)" {
            match &mut obj {
                Obj::Time(f) => Frame::set_unit(f, 1, value).unwrap(),
                Obj::Flux(f) => Frame::set_unit(f, 1, value).unwrap(),
                _ => unreachable!(),
            }
            continue;
        }
        match &mut obj {
            Obj::Time(f) => match name {
                "System" => f.set_system(TimeSystem::parse(value).unwrap()).unwrap(),
                "AlignSystem" => f.set_align_system(TimeSystem::parse(value).unwrap()),
                "TimeScale" => f.set_timescale(TimeScale::parse(value).unwrap()).unwrap(),
                "AlignTimeScale" => f.set_align_timescale(TimeScale::parse(value).unwrap()),
                "TimeOrigin" => f.set_time_origin_cur(dbl()).unwrap(),
                "LTOffset" => f.set_lt_offset(dbl()),
                other => panic!("unexpected setting {other}"),
            },
            Obj::Spec(f) => assert!(apply_spec(f, name, value), "unexpected setting {name}"),
            Obj::Dsb(f) => match name {
                // C reads Dsbcenter in the current units and IF in GHz.
                "DSBCentre" => f.set_dsb_centre_cur(dbl()).unwrap(),
                "IF" => f.set_if_ghz(dbl()),
                "SideBand" => f.set_sideband(SideBand::parse(value).unwrap()),
                "AlignSideBand" => f.set_align_sideband(value != "0"),
                _ => assert!(
                    apply_spec(f.spec_mut(), name, value),
                    "unexpected setting {name}"
                ),
            },
            Obj::Flux(f) => match name {
                "System" => f.set_system(FluxSystem::parse(value).unwrap()).unwrap(),
                "AlignSystem" => f.set_align_system(FluxSystem::parse(value).unwrap()),
                "SpecVal" => f.set_spec_val(dbl()),
                other => panic!("unexpected setting {other}"),
            },
        }
    }
    obj
}

fn fmt_sky(axis: usize, value: f64) -> String {
    SkyFrame::new(SkySystem::Fk5).format(axis, value).unwrap()
}

fn spec_value(f: &SpecFrame, attr: &str) -> Option<(V, bool)> {
    let s = |v: String| V::S(Box::leak(v.into_boxed_str()));
    Some(match attr {
        "System" => (s(f.system().as_str().to_string()), f.test_system()),
        "AlignSystem" => (
            s(f.align_system().as_str().to_string()),
            f.test_align_system(),
        ),
        "StdOfRest" => (
            s(f.std_of_rest().as_str().to_string()),
            f.test_std_of_rest(),
        ),
        "AlignStdOfRest" => (
            s(f.align_std_of_rest().as_str().to_string()),
            f.test_align_std_of_rest(),
        ),
        "RestFreq" => (V::D(f.rest_freq() / 1e9), f.test_rest_freq()),
        "RefRA" => (s(fmt_sky(1, f.ref_ra())), f.test_ref_ra()),
        "RefDec" => (s(fmt_sky(2, f.ref_dec())), f.test_ref_dec()),
        "SourceVel" => (V::D(f.source_vel_cur()), f.test_source_vel()),
        "SourceVRF" => (s(f.source_vrf().as_str().to_string()), f.test_source_vrf()),
        "SourceSys" => (s(f.source_sys().as_str().to_string()), f.test_source_sys()),
        "SpecOrigin" => (V::D(f.spec_origin_cur().unwrap()), f.test_spec_origin()),
        "AlignSpecOffset" => (
            V::I(i32::from(f.align_spec_offset())),
            f.test_align_spec_offset(),
        ),
        _ => return None,
    })
}

fn value(obj: &Obj, attr: &str) -> (V, Option<bool>) {
    let s = |v: String| V::S(Box::leak(v.into_boxed_str()));
    let f = obj.frame();
    let common = match attr {
        "Title" => Some((s(f.title().unwrap()), f.test_title())),
        "Domain" => Some((s(f.domain().to_string()), f.test_domain())),
        "Label(1)" => Some((s(f.label(1).unwrap()), f.test_label(1).unwrap())),
        "Symbol(1)" => Some((s(f.symbol(1).unwrap()), f.test_symbol(1).unwrap())),
        "Unit(1)" => Some((s(f.unit(1).unwrap()), f.test_unit(1).unwrap())),
        _ => None,
    };
    if let Some((v, t)) = common {
        return (v, Some(t));
    }
    let (v, t) = match obj {
        Obj::Time(f) => match attr {
            "System" => (s(f.system().as_str().to_string()), Some(f.test_system())),
            "AlignSystem" => (
                s(f.align_system().as_str().to_string()),
                Some(f.test_align_system()),
            ),
            "TimeScale" => (
                s(f.timescale().as_str().to_string()),
                Some(f.test_timescale()),
            ),
            "AlignTimeScale" => (
                s(f.align_timescale().as_str().to_string()),
                Some(f.test_align_timescale()),
            ),
            "TimeOrigin" => (V::D(f.time_origin_cur()), Some(f.test_time_origin())),
            "LTOffset" => (V::D(f.lt_offset()), Some(f.test_lt_offset())),
            other => panic!("unexpected attribute {other}"),
        },
        Obj::Spec(f) => {
            let (v, t) = spec_value(f, attr).unwrap();
            (v, Some(t))
        }
        Obj::Dsb(f) => match attr {
            "System" => (
                s(f.spec().system().as_str().to_string()),
                Some(f.spec().test_system()),
            ),
            "DSBCentre" => (V::D(f.dsb_centre_cur().unwrap()), Some(f.test_dsb_centre())),
            "IF" => (V::D(f.if_ghz()), Some(f.test_if())),
            "SideBand" => (
                s(f.sideband().as_str().to_string()),
                Some(f.test_sideband()),
            ),
            "AlignSideBand" => (
                V::I(i32::from(f.align_sideband())),
                Some(f.test_align_sideband()),
            ),
            "ImagFreq" => (V::D(f.imag_freq_ghz().unwrap()), None),
            other => {
                let (v, t) = spec_value(f.spec(), other).unwrap();
                (v, Some(t))
            }
        },
        Obj::Flux(f) => match attr {
            "System" => (
                s(f.system().unwrap().as_str().to_string()),
                Some(f.test_system()),
            ),
            "AlignSystem" => (
                s(f.align_system().as_str().to_string()),
                Some(f.test_align_system()),
            ),
            "SpecVal" => (
                s(if f.test_spec_val() {
                    format!("{}", f.spec_val())
                } else {
                    "<bad>".to_string()
                }),
                Some(f.test_spec_val()),
            ),
            other => panic!("unexpected attribute {other}"),
        },
    };
    (v, t)
}

/// Whether a value matches C's. Values C prints with `%.*g` are compared
/// as C prints them; doubles to 1e-12 relative, since several are converted
/// between unit systems.
fn matches(expected: V, got: V) -> bool {
    match (expected, got) {
        (V::D(e), V::D(g)) => e == g || (e - g).abs() <= 1e-12 * e.abs().max(1e-300),
        (V::S(e), V::S(g)) => {
            e == g
                || e.parse::<f64>()
                    .ok()
                    .zip(g.parse::<f64>().ok())
                    .is_some_and(|(a, b)| (a - b).abs() <= 1e-12 * a.abs())
        }
        (e, g) => e == g,
    }
}

#[test]
fn every_attribute_matches_the_c_library() {
    let mut failures = Vec::new();
    let mut last: Option<(&str, &str, Obj)> = None;
    for &(class, setting, attr, expected, expected_test) in cases::VALUE_CASES {
        if last
            .as_ref()
            .is_none_or(|(c, s, _)| (*c, *s) != (class, setting))
        {
            last = Some((class, setting, make(class, setting)));
        }
        let obj = &last.as_ref().unwrap().2;
        let (got, got_test) = value(obj, attr);
        if !matches(expected, got) || got_test != expected_test {
            failures.push(format!(
                "{class} {setting:?} {attr}: got {got:?} test {got_test:?}, C gives {expected:?} test {expected_test:?}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ:\n{}",
        failures.len(),
        cases::VALUE_CASES.len(),
        failures.join("\n")
    );
}

/// The dump the port writes is C's, and reading C's dump back gives an
/// object that writes it again.
#[test]
fn dump_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(class, setting, expected) in cases::DUMP_CASES {
        let written = native_dump(&make(class, setting).any()).unwrap();
        if written != expected {
            failures.push(format!(
                "dump for {class} {setting:?}:\n--- port\n{written}--- C\n{expected}"
            ));
            continue;
        }
        let rewritten = native_dump(&from_native_string(expected).unwrap()).unwrap();
        if rewritten != expected {
            failures.push(format!(
                "round trip of C's dump for {class} {setting:?}:\n--- port\n{rewritten}--- C\n{expected}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} dumps differ:\n{}",
        failures.len(),
        cases::DUMP_CASES.len(),
        failures.join("\n")
    );
}

/// A SpecFrame stores its Domain with white space removed and letters in
/// upper case, as C's `astSetC( specframe, "Domain", "my spec" )` gives
/// `"MYSPEC"`.
#[test]
fn spec_frame_domain_is_cleaned() {
    let mut sf = SpecFrame::new(SpecSystem::Freq);
    sf.set_domain("my spec");
    assert_eq!(Frame::domain(&sf), "MYSPEC");
}

/// A Dsbcenter with no topocentric frequency, such as a redshift of -1, is
/// rejected with AST__ATTIN and leaves the Dsbcenter unchanged, as C's
/// `astSetC( dsb, "DSBCentre", "-1.0" )` does for System=ZOPT.
#[test]
fn dsb_centre_with_no_topocentric_frequency_is_rejected() {
    let mut dsb = DSBSpecFrame::new(SpecSystem::Redshift);
    let before = dsb.dsb_centre();
    let err = dsb.set_dsb_centre_cur(-1.0).unwrap_err();
    assert_eq!(err.code(), starlink_ast::error::ErrorCode::Attin);
    assert_eq!(dsb.dsb_centre(), before);
    assert!(!dsb.test_dsb_centre());
}

/// A TimeFrame stores its Domain with white space removed and letters in
/// upper case, as C's `astSetC( timeframe, "Domain", "my time" )` gives
/// `"MYTIME"`.
#[test]
fn time_frame_domain_is_cleaned() {
    let mut tf = TimeFrame::new(TimeSystem::Mjd);
    tf.set_domain("my time");
    assert_eq!(Frame::domain(&tf), "MYTIME");
}

/// A FluxFrame stores its Domain cleaned, as C's
/// `astSetC( fluxframe, "Domain", "my flux" )` gives `"MYFLUX"`.
#[test]
fn flux_frame_domain_is_cleaned() {
    let mut ff = FluxFrame::new(FluxSystem::FluxDen);
    ff.set_domain("my flux");
    assert_eq!(Frame::domain(&ff), "MYFLUX");
}

/// A CmpFrame stores its Domain cleaned, and an empty Domain or Title is
/// a set value rather than a clear, as C's `astSetC( cmpframe, "Domain",
/// "my cmp" )` gives `"MYCMP"`, `astSetC( cmpframe, "Domain", "" )`
/// leaves `astTest( cmpframe, "Domain" )` true with the value `""`, and
/// `astSetC( cmpframe, "Title", "" )` leaves `astTest( cmpframe, "Title" )`
/// true.
#[test]
fn cmp_frame_domain_is_cleaned_and_empty_is_set() {
    let a = TimeFrame::new(TimeSystem::Mjd);
    let b = FluxFrame::new(FluxSystem::FluxDen);
    let mut cf = CmpFrame::new(Box::new(a), Box::new(b));
    cf.set_domain("my cmp");
    assert_eq!(Frame::domain(&cf), "MYCMP");
    cf.set_domain("");
    assert!(cf.test_domain());
    assert_eq!(Frame::domain(&cf), "");
    cf.set_title("");
    assert!(cf.test_title());
}
